from pathlib import Path
import re
W=Path(__file__).resolve().parent
add={
'art-137c':'''De verwijzingen in lid 1 hebben verschillende functies: artikel 175 lid 2 laat door de rechter-commissaris aangewezen huisraad aan de gefailleerde; artikel 176 regelt openbare of toegestane onderhandse verkoop en moeilijk te vereffenen baten; artikel 177 maakt betaalde inzet van de gefailleerde mogelijk. Bij de uitzondering op verkooptoestemming in artikel 176 telt de gezamenlijke beschreven waarde tot € 2.000, met eerdere verkopen erbij. Dat is geen vrijstelling per afzonderlijk goed. Artikel 194 betreft na-uitdeling op bevel van de rechtbank bij teruggevallen reserveringen of later ontdekte baten; het vervangt niet de regeling voor tijdens de vereffening opkomende baten in artikel 137g.''',
'art-137d':'''De verwijzing naar artikel 182 betreft concreet de omslag van algemene faillissementskosten over de boedeldelen en de daar omschreven uitzonderingen voor zelfexecutie. De uitkering op een gedekte vordering kan daarom niet los van de wijze van tegeldemaking en de toepasselijke kostenomslag worden berekend. Leg bijvoorbeeld bij een pandopbrengst vast wie heeft geëxecuteerd; het enkele bestaan van pandrecht bewijst nog niet dat alle algemene kosten buiten die opbrengst blijven.''',
'art-137e':'''Artikel 185 brengt een openbare behandeling, een schriftelijk rapport van de rechter-commissaris en een gemotiveerde rechtbankbeschikking mee. Via artikel 187 staat vervolgens binnen acht dagen na de beschikking cassatie open voor curator en iedere schuldeiser; het gaat niet om gewoon hoger beroep. De verwijzingen naar de normale inzagetermijn moeten overeenkomstig worden gelezen binnen de eigen tiendaagse neerlegging van artikel 137d. De definitieve binding van de lijst en het uitkeringsmoment worden samen met artikel 137f bepaald.''',
'art-137f':'''De afzonderlijk overgenomen bepalingen mogen niet verdwijnen achter het woord beëindiging. Artikel 188 betreft de gevolgen van levering na curatorverkoop voor hypotheken en bepaalde beperkte rechten. Artikel 189 verlangt dat voorwaardelijke en betwiste uitkeringen voorlopig worden gereserveerd; artikel 190 voorkomt dubbele betaling bij een latere opbrengst van verbonden goed. Artikel 192 regelt mede consignatie van gereserveerde of niet-opgenomen uitkeringen, terwijl artikel 193 de beëindiging, aankondiging, rekening en verantwoording en teruggave van boeken en papieren behandelt. Die overeenkomstige toepassing moet aansluiten bij lid 1: geldig verzet vereist eerst een onherroepelijke beschikking voordat de vastgestelde uitkering wordt gedaan.''',
'art-137g':'''De beschikking moet niet alleen een dag noemen: lid 1 verlangt uur, plaats en vergaderwijze overeenkomstig artikel 80a en verklaart artikel 108 toepasselijk. Het opnieuw toepasselijk worden van de zesde afdeling opent ook de gewone akkoordregeling; de omschakeling is dus ruimer dan uitsluitend verificatie van extra facturen. De bronnotitie over overgangsrecht is behouden. Voor oude procedures moet de toepasselijke overgangsregeling afzonderlijk worden onderzocht; de actuele tekst alleen beslist dat niet.''',
'art-138':'''Het aanbod aan de gezamenlijke schuldeisers maakt niet iedere schuld tot een door het uiteindelijke akkoord getroffen schuld. [HR 9 februari 2024, ECLI:NL:HR:2024:210](cases/HR-2024-210-akkoord-reikwijdte.md), rov. 3.1–3.7, beperkt de binding tot voor verificatie vatbare concurrente vorderingen. Niet door pand of hypotheek gedekte rente die tijdens faillissement loopt, valt daar niet onder. Een fictieve financier die twintig procent op de ingediende hoofdsommen aanbiedt, moet dus niet zonder nader onderzoek aannemen dat daarmee ook die latere rente definitief is afgedaan. Dit arrest beslist over de reikwijdte na homologatie, niet over de samenloopvoorwaarde met de in artikel 138 genoemde BW-overeenkomst.''',
'art-145':'''Met het wettelijke vorderingsbestand wordt hier het totale bedrag van de bedoelde toegelaten concurrente vorderingen bedoeld, ook van afwezige schuldeisers. In [Rb. Gelderland 14 juli 2015, ECLI:NL:RBGEL:2015:5785](cases/RBGEL-2015-5785-akkoordstemming.md), rov. 4.3–4.8, werd de beperktere uitleg tot de aanwezige crediteuren verworpen. Zestien voorstemmers hadden samen ongeveer € 574.000 van circa € 1,965 miljoen toegelaten concurrente schuld: brede steun onder de verschenen personen leverde daardoor niet de vereiste helft van het totale bedrag op. Dit is een uitleg door een rechtbank, geen uitspraak van de Hoge Raad; de hier relevante formulering van artikel 145 stemt overeen met de geselecteerde tekst.''',
'art-146':'''Afwezig blijven is niet zonder meer het tegenstemmen dat onderdeel b verlangt. In [Rb. Gelderland 14 juli 2015, ECLI:NL:RBGEL:2015:5785](cases/RBGEL-2015-5785-akkoordstemming.md), rov. 5.2–5.4, ontbrak volgens de rechtbank deze bevoegdheid omdat juist het wegblijven van de grootste schuldeiser de bedragdrempel onhaalbaar maakte. Ook zonder de daadwerkelijk uitgebrachte tegenstem was de vereiste helft niet gehaald. De schuldenaar bepleitte gelijkstelling van wegblijven en tegenstemmen, maar de rechtbank wees dat standpunt af. Het voorbeeld van de blokkerende grote crediteur hierboven veronderstelt daarom dat diens tegenstem de verwerping daadwerkelijk veroorzaakt.''',
'art-149':'''Een fout hoeft volgens [Rb. Gelderland 14 juli 2015, ECLI:NL:RBGEL:2015:5785](cases/RBGEL-2015-5785-akkoordstemming.md), rov. 4.2–4.8, niet uitsluitend een tel- of typefout te zijn: de rechtbank achtte artikel 149 ook geschikt voor beoordeling van een gestelde onjuiste uitleg van artikel 145. Het verzoek werd vervolgens inhoudelijk afgewezen omdat die uitleg juist werd bevonden. Dat onderscheid is wezenlijk: ontvankelijkheid van het soort herstelvraag bewijst nog niet dat de uitslag moet veranderen. De fout moet ook dan uit de stukken zelf blijken; deze rechtbankbeschikking geeft geen onbeperkte heropening van de stemming.'''
}
for p in (W/'commentary').glob('*.md'):
 s=p.read_text();chunks=re.split(r'(?m)(^=== \S+\s*$)',s);changed=False
 for i in range(1,len(chunks),2):
  k=chunks[i].strip()[4:]
  if k in add:
   t=chunks[i+1].strip()
   if k=='art-137g':t=t.replace('\n\n**Praktijkcontrole','\n\n'+add[k]+'\n\n**Praktijkcontrole')
   else:t+='\n\n'+add[k]
   chunks[i+1]='\n\n'+t+'\n\n';changed=True
 if changed:p.write_text(''.join(chunks).rstrip()+'\n')
